for (int i = 0; i <= 20; i += 5)
{
    Console.Write($"{i} ");
}
Console.WriteLine();

for (int i = 3; i >= 1; i--)
{
    Console.Write($"{i}... ");
}
Console.WriteLine("Los!");
// Ausgabe:
// 0 5 10 15 20
// 3... 2... 1... Los!

Console.Write("Wie viele Artikel? ");
int anzahl = int.Parse(Console.ReadLine());
int summe = 0;

for (int i = 1; i <= anzahl; i++)
{
    Console.Write($"Preis von Artikel {i} in Euro: ");
    summe += int.Parse(Console.ReadLine());
}
Console.WriteLine($"Gesamt: {summe} Euro");
// Eingaben: 3, 4, 2, 10
// Ausgabe (nach den Eingaben): Gesamt: 16 Euro

